  "Each request runs the prompt. Use {{body.path}}, {{headers.name}}, {{query.name}}, {{body}} or {{request}} in the prompt; only what it names reaches the agent.":
    "每次收到请求都会自动运行提示词。你可以在提示词里引用 {{body.path}}、{{headers.name}}、{{query.name}}、{{body}} 或 {{request}}；只有你明确引用的内容才会发给智能体。",
  "Official version (not translated)": "官方原版（未汉化）",
  "Shortcuts are environment-wide. Projects using the same action share its shortcut.":
    "快捷键在整台运行设备上通用，同名快捷操作在各个项目间共享同一个快捷键。",
  Updated: "已更新",
  "Show title details": "显示标题详情",
  "The previous request may have started. Open its thread to check before sending again.":
    "上一次请求可能已启动，请先打开对应对话确认，再重新发送。",
  "The previous request may already be running. Check its thread first. Allow another send that could create a duplicate thread?":
    "上一次请求可能正在运行，请先检查对应对话。仍要再次发送吗？这可能会创建重复的对话。",
  "Wait for attachments to finish preparing before rewinding.": "请等待附件准备完成后再回退。",
