  ", T3 Code needs Full Disk Access. Turn it on in System Settings, then come back to finish the import. You can revoke it again once the import is done.":
    "，T3 Code 需要“完全磁盘访问权限”。请前往系统设置开启后再回来完成导入，导入完成后随时可以关掉该权限。",
  ", then select Refresh.": "，然后点击“刷新”。",
  ", which is not available in this build. Its configuration is preserved.":
    "（当前版本暂不支持该驱动，你的配置已安全保留）。",
  "; switch to Stable to keep getting updates.": "；建议切回正式版（Stable）以继续接收后续更新。",
  ": Settings → Sharing & access → Authorized clients → Create link, then paste its code here.":
    "：依次打开“设置 → 共享与访问权限 → 已授权设备 → 创建配对链接”，然后把生成的口令粘贴到这里。",
  ": the host will merge this on its own once its requirements are met":
    "：满足所有检查要求后，代码托管平台会自动完成合并",
  ". An alpha that may change or break. T3 Code never installs Simlock.":
    "。早期预览功能，后续可能调整；T3 Code 不会自动安装 Simlock。",
  ". Anything set to use this generator falls back to the text generation model.":
    "。原本选用此服务的项目会自动改用默认文本生成模型。",
  ". Approve only if the device in front of you shows this code.":
    "。请务必核对你手头那台设备屏幕上显示的是同一个验证码后再批准。",
  ". Check the link's path or locate the file in Files.":
    "。请检查链接路径是否正确，或在“文件”栏中查找。",
  ". Dictation stays off until you choose another model.":
    "。重新选择其他语音模型前，语音输入将保持关闭。",
  ". Give it": "。请为它开启",
  ". Go home to choose a project or start a thread.": "。返回首页即可选择项目或开启新对话。",
  ". If": "。如果安装后",
  ". Open a new terminal to use": "。重新打开一个终端窗口即可使用",
  ". Read the prompt before you send it.": "。发送前请先过目确认提示词内容。",
  ". Save the file to read it in full.": "。保存文件到本地即可查看完整内容。",
  ". Search in the command palette.": "。你也可以在命令面板中搜索。",
  ". Switch any of these to it, or keep what they use now.":
    "。你可以把下面任意功能切换为使用它，也可以保持现有设置不变。",
  ". The agent can use that link as it is; change its access in Settings → Environments.":
    "。智能体可直接复用现有连接；如需调整权限，请前往“设置 → 运行设备”。",
  ". The link will be kept.": "，原有连接会保留。",
  ". The secrets themselves are untouched.": "，保存在密码库里的密钥本身不会被改动。",
  ". This choice applies only to this device.": "（此设置仅对当前设备生效）。",
  ". Turning it off stops every guest link.": "。关闭后所有正在分享的访客链接都会立即失效。",
  ". While off, nothing new starts over a link; running tasks finish.":
    "。关闭后不再接受新的跨设备调用，已在运行中的操作会正常跑完。",
