  "Run a prompt automatically on an interval, at a fixed time, once at a set date, or when a webhook is called.":
    "按固定间隔、每天/每周定点、指定日期单次，或在收到外部 Webhook 通知时，让智能体自动执行任务。",
  "Run agents on this computer. Turn off to use T3 Code only with remote environments.":
    "在当前电脑本机运行智能体与后台服务。如果你只把当前客户端当遥控器连接远程服务器，可以关闭此项省电省内存。",
  "Run interrupted": "本轮运行已中断",
  "Run the command on each machine to reclaim it. It restarts the background service. Quit the desktop app first if it hosts the environment.":
    "在对应电脑上执行整理命令即可释放闲置空间（期间会短暂重启后台服务；若由桌面客户端托管，请先退出桌面端）。",
  running: "正在运行",
