const DYNAMIC_WEB_SOURCE_RULES: ReadonlyArray<
  readonly [pattern: RegExp, replace: (...matches: string[]) => string]
> = [
  [/^Show full title: (.+)$/s, (title) => `查看完整标题：${title}`],
  [/^Show details: (.+)$/s, (detail) => `查看详情：${detail}`],
  [/^Snoozed, (.+) left$/, (left) => `已延后，剩余 ${left}`],
  [/^Snoozed until (.+)$/, (until) => `已延后至 ${until}`],
  [/^Settled (.+)$/, (when) => `已于 ${when} 归入已办`],
  [/^New thread in (.+)$/, (target) => `在 ${target} 中新建对话`],
  [/^New thread on (.+)$/, (branch) => `在 ${branch} 分支新建对话`],
  [/^No threads in (.+) yet$/, (project) => `${project} 里还没有对话`],
  [/^No active threads in (.+)$/, (project) => `${project} 中暂无待办对话`],
  [
    /^Step (\d+) of (\d+): (.+)$/,
    (step, total, label) => `第 ${step} / ${total} 步：${translateWebSource("zh-CN", label)}`,
  ],
  [/^Step (\d+) of (\d+)$/, (step, total) => `第 ${step} / ${total} 步`],
  [/^(\d+) of (\d+) on$/, (on, total) => `已开启 ${on} / ${total}`],
  [/^(\d+) of (\d+) selected$/, (sel, total) => `已选 ${sel} / ${total}`],
  [/^(\d+) of (\d+) checks? passed$/i, (ok, total) => `${ok} / ${total} 项检查已通过`],
  [/^(\d+) changed files?$/, (n) => `${n} 个改动文件`],
  [/^(\d+) more files?$/, (n) => `另外 ${n} 个文件`],
  [/^(\d+) files?$/, (n) => `${n} 个文件`],
  [/^(\d+) subagents? running$/, (n) => `${n} 个子智能体正在运行`],
  [/^(\d+) subagents?$/, (n) => `${n} 个子智能体`],
  [/^(\d+) agents?$/, (n) => `${n} 个智能体`],
  [/^(\d+) threads?$/, (n) => `${n} 个对话`],
  [/^(\d+) pull requests?$/, (n) => `${n} 个合并请求`],
  [/^(\d+) commits?$/, (n) => `${n} 次提交`],
  [/^(\d+) queued$/, (n) => `${n} 条排队中`],
  [/^Revoked (\d+) other clients?$/, (n) => `已下线另外 ${n} 台连接设备`],
  [/^This shortcut is (.+) in most apps\.$/, (key) => `大多数软件中此快捷键通常对应“${key}”。`],
  [/^Updated (.+)$/, (when) => `更新于 ${when}`],
  [/^Checked (.+)$/, (when) => `检查于 ${when}`],
  [/^Created (.+)$/, (when) => `创建于 ${when}`],
  [/^Merged (.+)$/, (when) => `合并于 ${when}`],
  [/^Closed (.+)$/, (when) => `关闭于 ${when}`],
  [/^Opened (.+)$/, (when) => `创建于 ${when}`],
  [/^Copy (.+) to clipboard$/, (item) => `复制 ${translateWebSource("zh-CN", item)}`],
  [/^Remove (.+) from this device\?$/, (name) => `确定将 ${name} 从当前客户端移除吗？`],
  [/^Pull request #(\d+)$/, (num) => `合并请求 #${num}`],
  [/^Stack #(\d+)$/, (num) => `关联组 #${num}`],
  [/^View stack #(\d+)$/, (num) => `查看关联组 #${num}`],
];

function translateDynamicWebSource(source: string): string | undefined {
  for (const [pattern, replace] of DYNAMIC_WEB_SOURCE_RULES) {
    const match = pattern.exec(source);
    if (match) {
      return replace(...match.slice(1));
    }
  }
  return undefined;
}

/** Translate static UI copy supplied by upstream components as English source text. */
export function translateWebSource(locale: ResolvedAppLocale, source: string): string {
  if (locale === "zh-CN") {
    const translatedSource = ZH_CN_SOURCE_MESSAGES[source];
    if (translatedSource !== undefined) return translatedSource;
  }
  const key = WEB_MESSAGE_KEY_BY_ENGLISH_SOURCE.get(source);
  if (key !== undefined) return WEB_MESSAGES[locale][key];
  if (locale === "zh-CN") {
    const dynamicTranslated = translateDynamicWebSource(source);
    if (dynamicTranslated !== undefined) return dynamicTranslated;
  }
  return source;
}

export function translateWebMessage(
  locale: ResolvedAppLocale,
  key: WebMessageKey,
  values?: WebMessageValues,
): string {
  const message = WEB_MESSAGES[locale][key];
  if (!values) return message;

  return message.replace(/\{([A-Za-z][A-Za-z0-9]*)\}/g, (placeholder, name: string) => {
    const value = values[name];
    return value === undefined ? placeholder : String(value);
  });
}
